// countdown.js\n// Provides a whimsical apocalypse countdown based on a fixed end date.\n\nfunction getApocalypseCountdown() {\n  const end = new Date('2099-12-31T23:59:59Z');\n  const now = new Date();\n  const diff = end - now;\n  const days = Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));\n  const messages = [\n    'The sky will turn neon pink.',\n    'Rats will learn to code.',\n    'All coffee will become sentient.',\n    'Cats will finally rule the internet.',\n    'Pizzas will grow on trees.'\n  ];\n  const message = messages[Math.floor(Math.random() * messages.length)];\n  return { days, message };\n}\n\nmodule.exports = { getApocalypseCountdown };\n
